ceName":"TANDON, Siddhi","sourceSail":"IND 1681"},{"sourceRank":140,"indexSailorId":"0a49ca82-2afb-4af7-bea7-b3fbca269157","sailorId":"e5f56ebd-25dc-46c8-82d5-19524355fe62","sourceName":"ALHWAIL, Mohammed","sourceSail":"KSA 101"},{"sourceRank":141,"indexSailorId":"137114f7-b20f-496f-94ac-20760afc8f91","sailorId":"c766be2b-32b7-4e38-9f7f-d31332e58c80","sourceName":"TATTARI, Chandralekha","sourceSail":"IND 1712"},{"sourceRank":142,"indexSailorId":"e9272fbe-ffef-4d5f-b683-877f788e5979","sailorId":"059779bb-5a2d-4ed7-b4e5-4c92b158174b","sourceName":"AL HUSSAINI, Habib","sourceSail":"OMA 310"},{"sourceRank":144,"indexSailorId":"a178a973-c4c8-45d1-a599-35ac5ad842e0","sailorId":"56b9b0d6-c67f-4521-8e2b-a4af7d7ac498","sourceName":"HASANOVA, Kamilla","sourceSail":"AZE 51"},{"sourceRank":145,"indexSailorId":"28fbfa38-8335-4fd9-ac3d-ef4c3a6c741f","sailorId":"4f380165-9a64-4366-911f-b15dacc6bbda","sourceName":"THAW, Khant Zin","sourceSail":"MYA 193"},{"sourceRank":147,"indexSailorId":"8efa3b47-dbed-430b-be62-b7609b3ea61f","sailorId":"8120aa0b-f353-4cae-8751-b00fe278f2c3","sourceName":"TANG, Chi In Jasper","sourceSail":"MAC 22"},{"sourceRank":148,"indexSailorId":"b983c299-dd95-459a-8507-d8684eee7ca6","sailorId":"27297fa9-0c02-4bd5-b8ef-925897a31bd6","sourceName":"AL MAHMOUD, Abdulaziz","sourceSail":"QAT 42"},{"sourceRank":149,"indexSailorId":"d037ec8d-2d9c-42f2-b2c7-0d342b8dc447","sailorId":"a51b8da2-b452-4c68-8c65-22d439799473","sourceName":"PERERA, Dhiren Aven","sourceSail":"SRI 201"},{"sourceRank":150,"indexSailorId":"5806a726-7832-4fd4-81b0-358d6fbd47ae","sailorId":"6808bfda-3c71-4f2f-b348-3e033d6fd86c","sourceName":"NIRUDU, Badrinath","sourceSail":"IND 1411"},{"sourceRank":151,"indexSailorId":"709467c5-7feb-42e0-83d7-47b772ffcc43","sailorId":"165daa17-07b6-4fc8-b4ce-60d74e99641f","sourceName":"ANEEQ, Luqmaan","sourceSail":"SRI 250"},{"sourceRank":153,"indexSailorId":"da55413e-3719-486a-9535-1951007a839e","sailorId":"bd4ab586-80f4-4c5e-81c0-d2a069d773ed","sourceName":"CHOI, Unho","sourceSail":"KOR 523"},{"sourceRank":154,"indexSailorId":"5d126e78-7517-4474-a0ee-20fec422eb3d","sailorId":"3db621df-d3f0-492e-8669-08bfd8ab0c86","sourceName":"PERERA, Binal","sourceSail":"SRI 224"},{"sourceRank":155,"indexSailorId":"7505d97f-f1a6-4322-922a-a426b2bb6b23","sailorId":"c5fb6a91-68f7-43c8-a701-bbd851f21426","sourceName":"KARUNARATNE, Mckaella","sourceSail":"SRI 202"},{"sourceRank":156,"indexSailorId":"489d4eee-8527-4aa7-9b40-0baae0be755e","sailorId":"5fb0c663-a7c4-401c-8a0d-b4f25d49893e","sourceName":"KIM, Hyeonsol","sourceSail":"KOR 480"},{"sourceRank":157,"indexSailorId":"41db410d-9f9b-49df-9fde-0b0e24426cca","sailorId":"5c71a2fa-f1d9-4e55-9e7a-f3ace88044a3","sourceName":"PARK, Daol","sourceSail":"KOR 584"},{"sourceRank":158,"indexSailorId":"af65cea3-0b88-41be-9307-37eb9e5c30cb","sailorId":"fa8ca139-1612-4a31-9d30-442d01744644","sourceName":"SK, Rameeza Bh","sourceSail":"IND 1716"},{"sourceRank":159,"indexSailorId":"6f182307-becf-4bd0-9b9d-d7a587de4e1f","sailorId":"50acb7b9-4896-454d-83a8-9c2dc2e1ed2b","sourceName":"AN, Siyeon","sourceSail":"KOR 589"},{"sourceRank":160,"indexSailorId":"2cc4af29-c476-4fb2-bd98-bdb936d57d75","sailorId":"16ef0da7-2a70-4547-b298-a136b9f07037","sourceName":"UBAYASIRI, Akaine","sourceSail":"SRI 208"},{"sourceRank":161,"indexSailorId":"2e6f37da-dc2e-4623-a7af-1414e7579f0f","sailorId":"4dcb32a7-727d-414f-b4c1-4da76dd36027","sourceName":"FERNANDO, Shem","sourceSail":"SRI 207"},{"sourceRank":163,"indexSailorId":"0feed282-76c0-4978-a34e-5bccf36d667e","sailorId":"a796d48c-c6ed-490c-b982-3415275e7285","sourceName":"AL RUZAIQI, Layan","sourceSail":"OMA 306"},{"sourceRank":164,"indexSailorId":"00ceb833-4c14-49ca-8644-bb7913906f8f","sailorId":"1aa36e44-2f42-4f33-a30e-81ffaf66337b","sourceName":"CHANG, Minkwan","sourceSail":"KOR 580"},{"sourceRank":165,"indexSailorId":"e4b5255e-494f-4a28-8c53-b0a10c9d0c19","sailorId":"c41bc960-6bac-42d2-9372-d711a94d63c2","sourceName":"AL YAFEI, Khalifa","sourceSail":"QAT 43"},{"sourceRank":166,"indexSailorId":"69bf097e-f296-46e6-80f5-a7da716ca0df","sailorId":"bbe926c6-581b-4400-8ba3-0d8b1182abae","sourceName":"HAZARI, Laila","sourceSail":"SRI 206"},{"sourceRank":167,"indexSailorId":"c19db40d-5407-4265-85ab-5a3e1ce804f1","sailorId":"8bc195f4-fb3b-47bf-b9c4-fb1d6009a75e","sourceName":"KIM, Jihoo","sourceSail":"KOR 562"},{"sourceRank":168,"indexSailorId":"fecf04fc-739d-4176-9610-3c2b92486c6d","sailorId":"696c9168-80f8-4fa7-a03c-8ed099e5545b","sourceName":"ALFORAIH, Abdulaziz","sourceSail":"KSA 105"},{"sourceRank":169,"indexSailorId":"06546159-08d7-4d75-be7f-76751bed9fa4","sailorId":"40a23367-69df-42e3-8907-be4a7919fb4e","sourceName":"AN, Seoyi","sourceSail":"KOR 586"},{"sourceRank":170,"indexSailorId":"32ad8a56-84f4-4753-9355-831541bf450a","sailorId":"a019873d-1cc3-4215-92a5-cd15d6d4b2c4","sourceName":"RAJAPAKSA, Ruwaneka","sourceSail":"SRI 203"}]}'::jsonb;
 g regattas%rowtype; r jsonb; p jsonb; race jsonb; a regatta_results%rowtype;
 replay boolean; actual jsonb; profile_ids uuid[]; profiles_before text; repair jsonb;
begin
 select exists(select 1 from admin_change_log where source=m->>'batch' and action='results.import_asian_overall' and entity_id=(m#>>'{sheet,id}')::uuid) into replay;
 perform 1 from regatta_events where id=(m#>>'{event,id}')::uuid for update;
 if not replay then
  if exists(select 1 from regatta_events where id=(m#>>'{event,id}')::uuid or slug=m#>>'{event,slug}' or lower(name)=lower(m#>>'{event,name}')) then raise exception 'New parent event collision'; end if;
 elsif not exists(select 1 from regatta_events where id=(m#>>'{event,id}')::uuid and slug=m#>>'{event,slug}' and start_date=(m#>>'{event,startDate}')::date and end_date=(m#>>'{event,endDate}')::date) then raise exception 'Parent event verification differs'; end if;
 select * into g from regattas where id=(m#>>'{sheet,id}')::uuid for update;
 if not replay and (m#>>'{sheet,existing}')::boolean then
  if g.id is null or g.event_id<>(m#>>'{event,id}')::uuid or g.boat_class<>m#>>'{sheet,boatClass}' or g.division<>m#>>'{sheet,division}' or g.date<>(m#>>'{event,startDate}')::date or g.status<>'published' or g.entry_type<>'individual' or g.counts_for_ranking<>(m#>>'{sheet,countsForRanking}')::boolean then raise exception 'Existing sheet identity/lifecycle changed'; end if;
 elsif not replay then
  if g.id is not null or exists(select 1 from regattas where slug=m#>>'{sheet,slug}' or (event_id=(m#>>'{event,id}')::uuid and boat_class=m#>>'{sheet,boatClass}' and division=m#>>'{sheet,division}')) then raise exception 'New sheet conflicts with an existing canonical class'; end if;
 end if;
 select array_agg((x->>'id')::uuid) into profile_ids from jsonb_array_elements(m->'profilePreflight') x;
 perform 1 from sailors where id=any(profile_ids) order by id for update;
 select md5(jsonb_agg(to_jsonb(s) order by s.id)::text) into profiles_before from sailors s where id=any(profile_ids);
 for p in select value from jsonb_array_elements(m->'indexPreflight') loop
  if not exists(select 1 from asian_optimist_index_sailors ix where ix.id=(p->>'indexSailorId')::uuid and ix.sailor_id=(p->>'sailorId')::uuid) then raise exception 'Index identity mapping changed before import'; end if;
 end loop;
 for p in select value from jsonb_array_elements(m->'profilePreflight') loop
  if not replay and not exists(select 1 from sailors s where s.id=(p->>'id')::uuid and jsonb_build_object('id',s.id,'name',s.name,'handle',s.handle,'sail_number',s.sail_number,'sail_number_ilca4',s.sail_number_ilca4,'board_number',s.board_number,'gender',s.gender,'nationality',s.nationality)=p) then raise exception 'Sailor identity preflight changed: %',p->>'name'; end if;
 end loop;
 perform 1 from regatta_results where regatta_id=(m#>>'{sheet,id}')::uuid order by id for update;
 perform 1 from regatta_result_participants where regatta_result_id in(select id from regatta_results where regatta_id=(m#>>'{sheet,id}')::uuid) order by id for update;
 if (select count(distinct x->>'sailorId') from jsonb_array_elements(m->'results') x)<>jsonb_array_length(m->'results') then raise exception 'Separate individual entries cannot share a sailor'; end if;
 if not replay then
  select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'sailor_id',x.sailor_id,'regatta_id',x.regatta_id,'rank',x.rank,'total_score',x.total_score,'nett_score',x.nett_score,'is_dns',x.is_dns,'is_overseas_commitment',x.is_overseas_commitment,'entry_type',x.entry_type,'entry_label',x.entry_label,'entry_sail_number',x.entry_sail_number,'entry_board_number',x.entry_board_number,'official_url',x.official_url,'evidence_url',x.evidence_url,'evidence_name',x.evidence_name,'evidence_notes',x.evidence_notes,'verification_status',x.verification_status) order by x.id),'[]'::jsonb) into actual from regatta_results x where regatta_id=(m#>>'{sheet,id}')::uuid;
  if actual is distinct from m->'beforeResults' then raise exception 'Result ownership/inventory changed'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'regatta_result_id',x.regatta_result_id,'sailor_id',x.sailor_id,'source_name',x.source_name,'display_order',x.display_order,'role',x.role,'match_status',x.match_status,'ranking_credit',x.ranking_credit) order by x.id),'[]'::jsonb) into actual from regatta_result_participants x join regatta_results rr on rr.id=x.regatta_result_id where rr.regatta_id=(m#>>'{sheet,id}')::uuid;
  if actual is distinct from m->'beforeParticipants' then raise exception 'Participant ownership/inventory changed'; end if;
  if exists(select 1 from regatta_race_results x join regatta_results rr on rr.id=x.regatta_result_id where rr.regatta_id=(m#>>'{sheet,id}')::uuid) then raise exception 'Existing race data requires reconciliation before mutation'; end if;
  if exists(select 1 from jsonb_array_elements(m->'beforeParticipants') x where x->>'role'<>'solo' or (x->>'display_order')::int<>1) then raise exception 'Conflicting individual participant structure'; end if;
  insert into admin_change_log(action,entity_type,entity_id,entity_label,summary,details,source)
  values('results.import_asian_overall','regatta',(m#>>'{sheet,id}')::uuid,m#>>'{sheet,name}','Imported visually reviewed official Asian & Oceanian class sheet with every race, code, discard, total, net and evidence link; explicit identity preflight.',jsonb_build_object('beforeSheet',to_jsonb(g),'beforeResults',(select jsonb_agg(to_jsonb(x)) from regatta_results x where regatta_id=(m#>>'{sheet,id}')::uuid),'beforeParticipants',(select jsonb_agg(to_jsonb(x)) from regatta_result_participants x join regatta_results rr on rr.id=x.regatta_result_id where rr.regatta_id=(m#>>'{sheet,id}')::uuid),'source',m->'officialSource','newProfiles',m->'newProfiles','identityCorrections',(select jsonb_agg(x) from jsonb_array_elements(m->'results') x where x ? 'previousSailorId'),'aliasRepair',m->'aliasRepair','createdEvent',m->'event','entryCount',jsonb_array_length(m->'results'),'raceCount',m#>'{sheet,raceCount}'),m->>'batch');
  for p in select value from jsonb_array_elements(m->'newProfiles') loop
   if exists(select 1 from sailors s where lower(s.name)=lower(p->>'name') or s.handle=p->>'handle' or s.id=(p->>'id')::uuid) then raise exception 'New sailor now exists: %',p->>'name'; end if;
   insert into sailors(id,name,handle,sail_number,sail_number_ilca4,gender,nationality,club,school)
   values((p->>'id')::uuid,p->>'name',p->>'handle',p->>'sail_number',p->>'sail_number_ilca4',p->>'gender',p->>'nationality',p->>'club',p->>'school');
  end loop;
  repair=m->'aliasRepair';
  if repair is not null then
   perform 1 from sailor_aliases where id=(repair->>'aliasId')::uuid for update;
   if not exists(select 1 from sailor_aliases where id=(repair->>'aliasId')::uuid and sailor_id=(repair->>'beforeSailorId')::uuid and alias_name=repair->>'aliasName') then raise exception 'Alix alias preflight changed'; end if;
   insert into admin_change_log(action,entity_type,entity_id,entity_label,summary,details,source) select 'sailors.correct_alias','sailor',(repair->>'sailorId')::uuid,repair->>'aliasName','Official sheet confirms separate individual entries for Alix and Margaux.',jsonb_build_object('beforeAlias',to_jsonb(x),'newSailorId',repair->>'sailorId','basis',repair->>'basis','audit','All five existing Alix/Margaux result/participant links reviewed and already correct. Existing Index links are correct and retained.'),m->>'batch' from sailor_aliases x where id=(repair->>'aliasId')::uuid;
   update sailor_aliases set sailor_id=(repair->>'sailorId')::uuid where id=(repair->>'aliasId')::uuid;
   insert into admin_change_log(action,entity_type,entity_id,entity_label,summary,details,source)
   values('sailors.duplicates.keep_separate','sailor',(repair->>'sailorId')::uuid,'Alix Nguyen-Minh / Margaux Nguyen-Minh','Official sheet lists these as separate individual sailors.',jsonb_build_object('pairKey',least(repair->>'sailorId',repair->>'beforeSailorId')||'|'||greatest(repair->>'sailorId',repair->>'beforeSailorId'),'aId',least(repair->>'sailorId',repair->>'beforeSailorId'),'bId',greatest(repair->>'sailorId',repair->>'beforeSailorId'),'aName',(select name from sailors where id=least(repair->>'sailorId',repair->>'beforeSailorId')::uuid),'bName',(select name from sailors where id=greatest(repair->>'sailorId',repair->>'beforeSailorId')::uuid),'reason',repair->>'basis'),m->>'batch');
  end if;
  insert into regatta_events(id,name,slug,start_date,end_date,venue,organizer,classes,nor_url,counts_for_ranking) values((m#>>'{event,id}')::uuid,m#>>'{event,name}',m#>>'{event,slug}',(m#>>'{event,startDate}')::date,(m#>>'{event,endDate}')::date,m#>>'{event,venue}',m#>>'{event,organizer}','["Optimist"]'::jsonb,m#>>'{event,norUrl}',false);
  if not (m#>>'{sheet,existing}')::boolean then
   insert into regattas(id,name,slug,event_id,date,end_date,total_fleet_size,division,race_count,geography,boat_class,entry_type,min_participants,max_participants,counts_for_ranking,venue,organizer,status,official_results_url,official_results_source_name,reviewed_at)
   values((m#>>'{sheet,id}')::uuid,m#>>'{sheet,name}',m#>>'{sheet,slug}',(m#>>'{event,id}')::uuid,(m#>>'{sheet,date}')::date,(m#>>'{sheet,endDate}')::date,(m#>>'{sheet,totalFleetSize}')::int,m#>>'{sheet,division}',(m#>>'{sheet,raceCount}')::int,m#>>'{sheet,geography}',m#>>'{sheet,boatClass}','individual',1,1,(m#>>'{sheet,countsForRanking}')::boolean,m#>>'{sheet,venue}',m#>>'{sheet,organizer}','published',m#>>'{officialSource,url}',m#>>'{officialSource,title}',now());
  else
   update regattas set end_date=(m#>>'{sheet,endDate}')::date,race_count=(m#>>'{sheet,raceCount}')::int,total_fleet_size=(m#>>'{sheet,totalFleetSize}')::int,official_results_url=m#>>'{officialSource,url}',official_results_source_name=m#>>'{officialSource,title}',reviewed_at=now(),updated_at=now() where id=(m#>>'{sheet,id}')::uuid;
  end if;
  for r in select value from jsonb_array_elements(m->'results') loop
   if exists(select 1 from regatta_results where regatta_id=(m#>>'{sheet,id}')::uuid and sailor_id=(r->>'sailorId')::uuid and id<>(r->>'resultId')::uuid) then raise exception 'Conflicting individual entry: %',r->>'name'; end if;
   select * into a from regatta_results where id=(r->>'resultId')::uuid;
   if a.id is not null and (a.regatta_id<>(m#>>'{sheet,id}')::uuid or a.sailor_id<>coalesce((r->>'previousSailorId')::uuid,(r->>'sailorId')::uuid)) then raise exception 'Explicit result owner mismatch'; end if;
   insert into regatta_results(id,sailor_id,regatta_id,entry_label,entry_sail_number,entry_board_number,entry_type,rank,total_score,nett_score,gender,nationality,is_dns,is_overseas_commitment,official_url,evidence_url,evidence_name,evidence_type,evidence_notes,verification_status,verified_at)
   values((r->>'resultId')::uuid,(r->>'sailorId')::uuid,(m#>>'{sheet,id}')::uuid,r->>'name',r->>'sailOrBoardNumber',case when m#>>'{sheet,boatClass}' in ('Techno 293','iQFOiL') then r->>'sailOrBoardNumber' else null end,'individual',(r->>'rank')::int,(r->>'grossScore')::real,(r->>'nettScore')::real,r->>'gender',r->>'nationality',false,false,m#>>'{officialSource,url}',m#>>'{officialSource,url}',m#>>'{officialSource,title}','pdf',r->>'evidenceNotes','verified',now())
   on conflict(id) do update set sailor_id=excluded.sailor_id,entry_label=excluded.entry_label,entry_sail_number=excluded.entry_sail_number,entry_board_number=excluded.entry_board_number,rank=excluded.rank,total_score=excluded.total_score,nett_score=excluded.nett_score,gender=excluded.gender,nationality=excluded.nationality,birth_year=case when regatta_results.sailor_id<>excluded.sailor_id then (select extract(year from dob)::int from sailors where id=excluded.sailor_id) else regatta_results.birth_year end,is_dns=false,is_overseas_commitment=false,official_url=excluded.official_url,evidence_url=excluded.evidence_url,evidence_name=excluded.evidence_name,evidence_type='pdf',evidence_notes=concat_ws(E'\n',nullif(regatta_results.evidence_notes,''),excluded.evidence_notes),verification_status='verified',verified_at=now(),updated_at=now();
   insert into regatta_result_participants(id,regatta_result_id,sailor_id,source_name,display_order,role,match_status,ranking_credit)
   values((r->>'participantId')::uuid,(r->>'resultId')::uuid,(r->>'sailorId')::uuid,r->>'name',1,'solo','matched',(m#>>'{sheet,countsForRanking}')::boolean)
   on conflict(id) do update set sailor_id=excluded.sailor_id,source_name=excluded.source_name,role='solo',match_status='matched',ranking_credit=excluded.ranking_credit,updated_at=now();
   insert into regatta_race_results(regatta_result_id,race_number,score,scoring_code,discarded,raw_value)
   select (r->>'resultId')::uuid,(x->>'raceNumber')::int,(x->>'score')::real,x->>'code',(x->>'discarded')::boolean,x->>'raw' from jsonb_array_elements(r->'races') x;
  end loop;
 end if;
 if not exists(select 1 from regattas where id=(m#>>'{sheet,id}')::uuid and boat_class=m#>>'{sheet,boatClass}' and division=m#>>'{sheet,division}' and race_count=(m#>>'{sheet,raceCount}')::int and total_fleet_size=(m#>>'{sheet,totalFleetSize}')::int and status='published' and counts_for_ranking=(m#>>'{sheet,countsForRanking}')::boolean and official_results_url=m#>>'{officialSource,url}' and official_results_source_name=m#>>'{officialSource,title}' and event_id=(m#>>'{event,id}')::uuid) then raise exception 'Final metadata differs'; end if;
 if (select count(*) from regatta_results where regatta_id=(m#>>'{sheet,id}')::uuid)<>jsonb_array_length(m->'results') then raise exception 'Final entry count differs'; end if;
 for r in select value from jsonb_array_elements(m->'results') loop
  if not exists(select 1 from regatta_results where id=(r->>'resultId')::uuid and regatta_id=(m#>>'{sheet,id}')::uuid and sailor_id=(r->>'sailorId')::uuid and entry_label=r->>'name' and entry_sail_number=r->>'sailOrBoardNumber' and nationality=r->>'nationality' and gender=r->>'gender' and rank=(r->>'rank')::int and total_score=(r->>'grossScore')::real and nett_score=(r->>'nettScore')::real and evidence_url=m#>>'{officialSource,url}' and official_url=m#>>'{officialSource,url}' and evidence_name=m#>>'{officialSource,title}' and verification_status='verified' and not is_dns and not is_overseas_commitment) then raise exception 'Result/evidence verification failed: %',r->>'name'; end if;
  if (select count(*) from regatta_result_participants where regatta_result_id=(r->>'resultId')::uuid)<>1 or not exists(select 1 from regatta_result_participants where id=(r->>'participantId')::uuid and regatta_result_id=(r->>'resultId')::uuid and sailor_id=(r->>'sailorId')::uuid and source_name=r->>'name' and display_order=1 and role='solo' and ranking_credit=(m#>>'{sheet,countsForRanking}')::boolean) then raise exception 'Participant verification failed'; end if;
  if (select count(*) from regatta_race_results where regatta_result_id=(r->>'resultId')::uuid)<>jsonb_array_length(r->'races') then raise exception 'Race count differs'; end if;
  for race in select value from jsonb_array_elements(r->'races') loop
   if not exists(select 1 from regatta_race_results where regatta_result_id=(r->>'resultId')::uuid and race_number=(race->>'raceNumber')::int and score=(race->>'score')::real and scoring_code is not distinct from race->>'code' and discarded=(race->>'discarded')::boolean and raw_value=race->>'raw') then raise exception 'Race value/code/discard differs'; end if;
  end loop;
  if exists(select 1 from regatta_race_results where regatta_result_id=(r->>'resultId')::uuid group by regatta_result_id having abs(sum(score)-(r->>'grossScore')::real)>.001 or abs(sum(score) filter(where not discarded)-(r->>'nettScore')::real)>.001 or count(*) filter(where discarded)<>(m#>>'{sheet,discardCount}')::int) then raise exception 'Score reconciliation failed'; end if;
 end loop;
 if profiles_before is distinct from(select md5(jsonb_agg(to_jsonb(s) order by s.id)::text) from sailors s where id=any(profile_ids)) then raise exception 'Existing athlete fields changed'; end if;
 if m ? 'aliasRepair' and not exists(select 1 from sailor_aliases where id=(m#>>'{aliasRepair,aliasId}')::uuid and sailor_id=(m#>>'{aliasRepair,sailorId}')::uuid and alias_name=m#>>'{aliasRepair,aliasName}') then raise exception 'Alias repair differs'; end if;
end
$import$;
commit;
